import type { ListQuery } from '@athene-x/whimui/list-query';

import { IconSearch } from '@tabler/icons-react';

import { InputGroup, InputGroupAddon, InputGroupInput } from '@/components/ui/input-group';

export type ListSearchInputProps = {
  list: Pick<ListQuery, 'searchInput' | 'setSearchInput'>;
  label: string;
  placeholder?: string;
  className?: string;
};

/** Debounced free-text search bound to a `useListQuery` (the API's `searchTerm`). */
export function ListSearchInput({
  list,
  label,
  placeholder = label,
  className,
}: ListSearchInputProps) {
  return (
    <InputGroup className={className}>
      <InputGroupAddon>
        <IconSearch />
      </InputGroupAddon>
      <InputGroupInput
        type="search"
        aria-label={label}
        placeholder={placeholder}
        value={list.searchInput}
        onChange={(event) => list.setSearchInput(event.target.value)}
      />
    </InputGroup>
  );
}

import type { ListQuery } from '@athene-x/whimui/list-query';

import { FilterSelect, type FilterSelectProps } from '@/components/filter-select';

export type ListFilterSelectProps<TField extends string> = Omit<
  FilterSelectProps,
  'value' | 'onChange'
> & {
  list: Pick<ListQuery<string, TField>, 'getFilter' | 'setFilter'>;
  field: TField;
};

/** Single-value filter bound to a `useListQuery` field (sent as `field:in:value`). */
export function ListFilterSelect<TField extends string>({
  list,
  field,
  ...props
}: ListFilterSelectProps<TField>) {
  return (
    <FilterSelect
      {...props}
      value={list.getFilter(field)[0] ?? ''}
      onChange={(value) => list.setFilter(field, value ? [value] : [])}
    />
  );
}

import { NativeSelect, NativeSelectOption } from '@/components/ui/native-select';

export type FilterOption = {
  value: string;
  label: string;
};

export type FilterSelectProps = {
  label: string;
  allLabel: string;
  options: readonly FilterOption[] | undefined;
  value: string;
  onChange: (value: string) => void;
  className?: string;
};

/** Single-value filter as a native `<select>`, with an "all" option that clears it. */
export function FilterSelect({
  label,
  allLabel,
  options,
  value,
  onChange,
  className,
}: FilterSelectProps) {
  return (
    <NativeSelect
      className={className}
      aria-label={label}
      value={value}
      onChange={(event) => onChange(event.target.value)}
    >
      <NativeSelectOption value="">{allLabel}</NativeSelectOption>
      {options?.map((option) => (
        <NativeSelectOption key={option.value} value={option.value}>
          {option.label}
        </NativeSelectOption>
      ))}
    </NativeSelect>
  );
}
